// Bundles the web UI into web/dist (embedded into Emdedown.exe by the C# build).
import * as esbuild from 'esbuild';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const out = path.join(here, 'dist');
const dev = process.argv.includes('--dev');
// Generated by tools/make-notices.mjs (not during the build, so changes to it get reviewed).
const notices = path.join(here, '../THIRD-PARTY-NOTICES.md');
if (!fs.existsSync(notices)) {
  console.error('THIRD-PARTY-NOTICES.md is missing. Run `node tools/make-notices.mjs` from the project root (after npm ci in web/).');
  process.exit(1);
}

fs.rmSync(out, { recursive: true, force: true });
fs.mkdirSync(path.join(out, 'fonts'), { recursive: true });

await esbuild.build({
  entryPoints: [path.join(here, 'src/app.js')],
  outdir: out,
  bundle: true,
  splitting: true,
  format: 'esm',
  target: ['chrome120'],
  minify: !dev,
  sourcemap: dev ? 'inline' : false,
  chunkNames: 'chunks/[name]-[hash]',
  legalComments: 'none',
  logLevel: 'warning',
  define: { 'process.env.NODE_ENV': '"production"' },
});

await esbuild.build({
  entryPoints: { app: path.join(here, 'src/styles/app.css'), export: path.join(here, 'src/styles/export.css') },
  outdir: out,
  bundle: true,
  minify: !dev,
  target: ['chrome120'],
  logLevel: 'warning',
});

// KaTeX css + woff2 fonts only (every Chromium supports woff2).
const kdir = path.join(here, 'node_modules/katex/dist');
let kcss = fs.readFileSync(path.join(kdir, 'katex.min.css'), 'utf8');
kcss = kcss.replace(/,url\(fonts\/[^)]+\.woff\) format\("woff"\)/g, '').replace(/,url\(fonts\/[^)]+\.ttf\) format\("truetype"\)/g, '');
fs.writeFileSync(path.join(out, 'katex.css'), kcss);
for (const f of fs.readdirSync(path.join(kdir, 'fonts'))) if (f.endsWith('.woff2')) fs.copyFileSync(path.join(kdir, 'fonts', f), path.join(out, 'fonts', f));

fs.copyFileSync(path.join(here, 'src/index.html'), path.join(out, 'index.html'));

// Licences, shown in About (the exe is distributed alone).
const license = path.join(here, '../LICENSE');
let lic = 'Emdedown is free software, released under the MIT License.\n\n';
if (fs.existsSync(license)) lic += fs.readFileSync(license, 'utf8').replace(/^﻿/, '').trim() + '\n\n';
lic += '='.repeat(72) + '\n\n' + fs.readFileSync(notices, 'utf8').replace(/^﻿/, '');
fs.writeFileSync(path.join(out, 'licenses.txt'), lic.replace(/\r\n?/g, '\n'));

let total = 0; let count = 0;
const walk = (d) => { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else { total += fs.statSync(p).size; count++; } } };
walk(out);
console.log(`web bundle: ${count} files, ${(total / 1024 / 1024).toFixed(2)} MB`);
